CREATE FUNCTION public.ppm_snapshot() RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE result jsonb; u jsonb; roles text[]; BEGIN IF NOT public.ppm_ativo() THEN RAISE EXCEPTION 'Acesso não autorizado' USING ERRCODE='42501'; END IF; SELECT array_agg(papel) INTO roles FROM public.ppm_papeis WHERE user_id=auth.uid(); SELECT jsonb_build_object('id',p.id,'nome',p.display_name,'email',p.email,'cargo',p.job_title,'iniciais',upper(left(p.display_name,2)),'perfil',CASE WHEN 'administrador_pmo'=ANY(roles) THEN 'Administrador/PMO' WHEN 'auditor'=ANY(roles) THEN 'Auditor' WHEN 'alta_administracao'=ANY(roles) THEN 'Alta Administração' WHEN 'gestor'=ANY(roles) THEN 'Gestor' ELSE 'Técnico' END) INTO u FROM public.profiles p WHERE id=auth.uid();
SELECT jsonb_build_object(
'usuario',u,'capacidades',coalesce(to_jsonb(roles),'[]'),
'usuarios',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',display_name,'email',email,'cargo',job_title,'iniciais',upper(left(display_name,2)),'perfil',CASE WHEN id=auth.uid() THEN u->>'perfil' ELSE 'Usuário autorizado' END)) FROM public.profiles),'[]'),
'areas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'nome',a.nome,'sigla',a.sigla,'responsavel',a.responsavel,'visibilidade',a.visibilidade,'membros',coalesce((SELECT jsonb_agg(jsonb_build_object('usuarioId',usuario_id,'papel',papel)) FROM public.area_membros WHERE area_id=a.id),'[]'))) FROM public.areas a),'[]'),
'objetos',coalesce((SELECT jsonb_object_agg(id,jsonb_build_object('areaId',area_id,'visibilidade',visibilidade,'convidados',convidados,'compartilhadoCom',compartilhado_com)) FROM public.objetos_acesso),'{}'),
'permissoes',coalesce((SELECT jsonb_object_agg(id,public.ppm_pode_editar(id)) FROM public.objetos_acesso),'{}'),
'portfolios',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'areaId',f.area_id,'responsavelId',f.responsavel_id,'nome',f.nome,'tipo',f.tipo,'responsavel',f.responsavel,'orcamento',t.orcamento_projetos,'executado',t.executado,'progresso',t.progresso,'saude',f.saude,'prioridade',f.prioridade,'score',f.score,'programas',t.programas,'projetos',t.projetos,'riscosCriticos',t.riscos_criticos)) FROM public.portfolios f JOIN public.totais_portfolio t ON t.id=f.id),'[]'),
'programas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'nome',g.nome,'portfolioId',g.portfolio_id,'gerente',g.gerente,'objetivo',g.objetivo,'saude',g.saude,'progresso',t.progresso,'metas',coalesce((SELECT jsonb_agg(jsonb_build_object('nome',nome,'alvo',alvo,'atual',atual,'unidade',unidade)) FROM public.programa_metas WHERE programa_id=g.id),'[]'))) FROM public.programas g JOIN public.totais_programa t ON t.id=g.id),'[]'),
'projetos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'nome',p.nome,'programaId',p.programa_id,'gerente',p.gerente,'metodologia',p.metodologia,'status',p.status,'inicio',p.inicio,'fim',p.fim,'orcamento',p.orcamento,'executado',p.executado,'progresso',p.progresso,'saude',p.saude,'escopo',p.escopo,'objetivoId',coalesce((SELECT objetivo_id::text FROM public.alinhamento_estrategico WHERE objeto_id=p.id LIMIT 1),''))) FROM public.projetos p),'[]'),
'objetivos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'codigo',o.codigo,'nome',o.nome,'perspectiva',o.perspectiva,'meta',o.meta,'responsavel',o.responsavel,'aderencia',coalesce((SELECT round(avg(p.progresso),2) FROM public.projetos p JOIN public.alinhamento_estrategico a ON a.objeto_id=p.id WHERE a.objetivo_id=o.id),0))) FROM public.objetivos_estrategicos o),'[]'),
'riscos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'nome',r.nome,'categoria',r.categoria,'origem',r.origem,'probabilidade',r.probabilidade,'impacto',r.impacto,'resposta',r.resposta,'plano',coalesce((SELECT string_agg(acao,'; ') FROM public.risco_planos WHERE risco_id=r.id),''),'responsavel',r.responsavel,'prazo',r.prazo,'tendencia',r.tendencia)) FROM public.riscos r),'[]'),
'indicadores',coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'nome',i.nome,'formula',i.formula,'unidade',i.unidade,'meta',i.meta,'polaridade',i.polaridade,'periodicidade',i.periodicidade,'responsavel',i.responsavel,'atual',CASE WHEN i.calculo='execucao' THEN (SELECT coalesce(round(100*sum(executado)/nullif(sum(orcamento),0),2),0) FROM public.projetos) WHEN i.calculo='prazo' THEN (SELECT coalesce(round(100.0*count(*) FILTER(WHERE status='Concluído' OR fim>=current_date)/nullif(count(*),0),2),0) FROM public.projetos) ELSE coalesce((SELECT valor FROM public.indicador_valores WHERE indicador_id=i.id ORDER BY periodo DESC LIMIT 1),0) END,'historico',coalesce((SELECT jsonb_agg(jsonb_build_object('periodo',to_char(periodo,'YYYY-MM'),'valor',valor) ORDER BY periodo) FROM public.indicador_valores WHERE indicador_id=i.id),'[]'))) FROM public.indicadores i),'[]'),
'elementos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'projetoId',e.projeto_id,'nome',e.nome,'responsavel',e.responsavel,'status',e.status,'prazo',e.prazo,'progresso',e.progresso,'subelementos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'elementoId',s.elemento_id,'nome',s.nome,'responsavel',s.responsavel,'status',s.status,'prazo',s.prazo,'progresso',s.progresso)) FROM public.projeto_subelementos s WHERE s.elemento_id=e.id),'[]'))) FROM public.projeto_elementos e),'[]'),
'atualizacoes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'projetoId',a.projeto_id,'alvoTipo',a.alvo_tipo,'alvoId',a.alvo_id,'autor',a.autor,'criadaEm',a.created_at,'texto',a.texto) ORDER BY a.created_at DESC) FROM public.projeto_atualizacoes a),'[]'),
'statusReports',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'projetoId',s.projeto_id,'periodo',s.periodo,'autor',s.autor,'saude',s.saude,'resumo',s.resumo)) FROM public.status_reports s),'[]'),
'tarefas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'projetoId',t.projeto_id,'titulo',t.titulo,'responsavel',t.responsavel,'status',t.status,'pontos',t.pontos)) FROM public.projeto_tarefas t),'[]'),
'cronograma',coalesce((SELECT jsonb_agg(jsonb_build_object('projetoId',t.projeto_id,'fase',t.titulo,'inicio',(t.inicio-p.inicio)/7.0,'duracao',(t.fim-t.inicio)/7.0,'progresso',t.progresso)) FROM public.projeto_tarefas t JOIN public.projetos p ON p.id=t.projeto_id WHERE t.inicio IS NOT NULL AND t.fim IS NOT NULL),'[]'),
'views',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'escopo',escopo,'blocos',blocos,'perfis',perfis,'areas',areas)) FROM public.views_usuario),'[]'),
'etiquetas',jsonb_build_object('tipo',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'tom',tom)) FROM public.etiquetas_carteira WHERE coluna='tipo'),'[]'),'status',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'tom',tom)) FROM public.etiquetas_carteira WHERE coluna='status'),'[]'),'metodologia',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'tom',tom)) FROM public.etiquetas_carteira WHERE coluna='metodologia'),'[]')),
'log',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'quando',to_char(created_at AT TIME ZONE 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'),'usuario',coalesce((SELECT display_name FROM public.profiles WHERE id=a.user_id),'Usuário autorizado'),'perfil','','acao',event_type,'entidade',entity_type,'detalhe',result)) FROM (SELECT * FROM public.security_audit_log ORDER BY created_at DESC LIMIT 100)a),'[]'),
'totais',(SELECT to_jsonb(t) FROM public.totais_institucionais t)
) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.ppm_snapshot() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_snapshot() TO authenticated;
CREATE FUNCTION public.ppm_mutar(tabela text,acao text,dados jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE i uuid:=coalesce(nullif(dados->>'id','')::uuid,gen_random_uuid()); a uuid; r uuid; v jsonb; c text; BEGIN IF NOT public.ppm_ativo() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; IF tabela NOT IN ('portfolios','programas','projetos','areas','projeto_elementos','projeto_subelementos','projeto_atualizacoes','views_usuario','etiquetas_carteira') THEN RAISE EXCEPTION 'Tabela inválida'; END IF;
IF acao='remover' THEN EXECUTE format('DELETE FROM public.%I WHERE id=$1',tabela) USING i; IF NOT FOUND THEN RAISE EXCEPTION 'Registro não encontrado ou sem permissão'; END IF; RETURN i; END IF;
IF tabela='portfolios' THEN a:=nullif(dados->>'areaId','')::uuid; IF a IS NULL THEN SELECT area_id INTO a FROM public.portfolios WHERE id=i; END IF; IF a IS NULL THEN SELECT id INTO a FROM public.areas ORDER BY created_at LIMIT 1; END IF; SELECT id INTO r FROM public.profiles WHERE display_name=dados->>'responsavel' LIMIT 1; INSERT INTO public.portfolios(id,area_id,nome,tipo,responsavel,responsavel_id,orcamento,prioridade,score,saude) VALUES(i,a,dados->>'nome',dados->>'tipo',dados->>'responsavel',r,coalesce((dados->>'orcamento')::numeric,0),coalesce((dados->>'prioridade')::int,1),coalesce((dados->>'score')::numeric,0),coalesce(dados->>'saude','verde')) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,tipo=excluded.tipo,responsavel=excluded.responsavel,responsavel_id=excluded.responsavel_id,orcamento=excluded.orcamento,prioridade=excluded.prioridade,score=excluded.score,saude=excluded.saude;
ELSIF tabela='programas' THEN SELECT id INTO r FROM public.profiles WHERE display_name=dados->>'gerente' LIMIT 1; INSERT INTO public.programas(id,portfolio_id,nome,objetivo,gerente,gerente_id,saude) VALUES(i,(dados->>'portfolioId')::uuid,dados->>'nome',dados->>'objetivo',dados->>'gerente',r,coalesce(dados->>'saude','verde')) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,portfolio_id=excluded.portfolio_id,objetivo=excluded.objetivo,gerente=excluded.gerente,gerente_id=excluded.gerente_id,saude=excluded.saude; DELETE FROM public.programa_metas WHERE programa_id=i; FOR v IN SELECT * FROM jsonb_array_elements(coalesce(dados->'metas','[]')) LOOP INSERT INTO public.programa_metas(programa_id,nome,alvo,atual,unidade) VALUES(i,v->>'nome',(v->>'alvo')::numeric,(v->>'atual')::numeric,v->>'unidade'); END LOOP;
ELSIF tabela='projetos' THEN SELECT id INTO r FROM public.profiles WHERE display_name=dados->>'gerente' LIMIT 1; INSERT INTO public.projetos(id,programa_id,nome,gerente,gerente_id,metodologia,status,inicio,fim,orcamento,executado,progresso,saude) VALUES(i,(dados->>'programaId')::uuid,dados->>'nome',dados->>'gerente',r,dados->>'metodologia',dados->>'status',(dados->>'inicio')::date,(dados->>'fim')::date,(dados->>'orcamento')::numeric,(dados->>'executado')::numeric,(dados->>'progresso')::numeric,dados->>'saude') ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,programa_id=excluded.programa_id,gerente=excluded.gerente,gerente_id=excluded.gerente_id,metodologia=excluded.metodologia,status=excluded.status,inicio=excluded.inicio,fim=excluded.fim,orcamento=excluded.orcamento,executado=excluded.executado,progresso=excluded.progresso,saude=excluded.saude;
ELSIF tabela='areas' THEN SELECT id INTO r FROM public.profiles WHERE display_name=dados->>'responsavel' LIMIT 1; INSERT INTO public.areas(id,nome,sigla,responsavel,responsavel_id,visibilidade) VALUES(i,dados->>'nome',dados->>'sigla',dados->>'responsavel',r,dados->>'visibilidade') ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,sigla=excluded.sigla,responsavel=excluded.responsavel,responsavel_id=excluded.responsavel_id,visibilidade=excluded.visibilidade; DELETE FROM public.area_membros WHERE area_id=i; FOR v IN SELECT * FROM jsonb_array_elements(coalesce(dados->'membros','[]')) LOOP INSERT INTO public.area_membros(area_id,usuario_id,papel) VALUES(i,(v->>'usuarioId')::uuid,v->>'papel'); END LOOP;
ELSIF tabela='projeto_elementos' THEN SELECT id INTO r FROM public.profiles WHERE display_name=dados->>'responsavel' LIMIT 1; INSERT INTO public.projeto_elementos(id,projeto_id,nome,responsavel,responsavel_id,status,prazo,progresso) VALUES(i,(dados->>'projetoId')::uuid,dados->>'nome',dados->>'responsavel',r,dados->>'status',(dados->>'prazo')::date,(dados->>'progresso')::numeric) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,responsavel=excluded.responsavel,responsavel_id=excluded.responsavel_id,status=excluded.status,prazo=excluded.prazo,progresso=excluded.progresso;
ELSIF tabela='projeto_subelementos' THEN SELECT id INTO r FROM public.profiles WHERE display_name=dados->>'responsavel' LIMIT 1; INSERT INTO public.projeto_subelementos(id,projeto_id,elemento_id,nome,responsavel,responsavel_id,status,prazo,progresso) VALUES(i,(dados->>'projetoId')::uuid,(dados->>'elementoId')::uuid,dados->>'nome',dados->>'responsavel',r,dados->>'status',(dados->>'prazo')::date,(dados->>'progresso')::numeric) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,responsavel=excluded.responsavel,responsavel_id=excluded.responsavel_id,status=excluded.status,prazo=excluded.prazo,progresso=excluded.progresso;
ELSIF tabela='projeto_atualizacoes' THEN SELECT display_name INTO c FROM public.profiles WHERE id=auth.uid(); INSERT INTO public.projeto_atualizacoes(id,projeto_id,alvo_tipo,alvo_id,autor,texto) VALUES(i,(dados->>'projetoId')::uuid,dados->>'alvoTipo',(dados->>'alvoId')::uuid,c,dados->>'texto');
ELSIF tabela='views_usuario' THEN INSERT INTO public.views_usuario(id,nome,escopo,blocos,perfis,areas) VALUES(i,dados->>'nome',dados->>'escopo',ARRAY(SELECT jsonb_array_elements_text(dados->'blocos')),ARRAY(SELECT jsonb_array_elements_text(dados->'perfis')),ARRAY(SELECT jsonb_array_elements_text(dados->'areas')::uuid)) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,blocos=excluded.blocos,perfis=excluded.perfis,areas=excluded.areas;
ELSIF tabela='etiquetas_carteira' THEN c:=dados->>'coluna'; DELETE FROM public.etiquetas_carteira WHERE coluna=c; FOR v IN SELECT * FROM jsonb_array_elements(dados->'lista') LOOP INSERT INTO public.etiquetas_carteira(coluna,nome,tom) VALUES(c,v->>'nome',v->>'tom'); END LOOP; FOR c,v IN SELECT key,value FROM jsonb_each(coalesce(dados->'renomes','{}')) LOOP IF dados->>'coluna'='tipo' THEN UPDATE public.portfolios SET tipo=v#>>'{}' WHERE tipo=c; ELSIF dados->>'coluna'='status' THEN UPDATE public.projetos SET status=v#>>'{}' WHERE status=c; ELSE UPDATE public.projetos SET metodologia=v#>>'{}' WHERE metodologia=c; END IF; END LOOP;
END IF; RETURN i; END $$;
REVOKE ALL ON FUNCTION public.ppm_mutar(text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_mutar(text,text,jsonb) TO authenticated;
CREATE FUNCTION public.ppm_alterar_acesso(objeto uuid,parcial jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.objetos_acesso; n text; v jsonb; BEGIN IF NOT public.ppm_tem_papel('administrador_pmo') THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; SELECT * INTO r FROM public.objetos_acesso WHERE id=objeto; IF NOT FOUND THEN RAISE EXCEPTION 'Objeto inexistente'; END IF; IF parcial?'areaId' AND (parcial->>'areaId')::uuid<>r.area_id THEN RAISE EXCEPTION 'Movimentação de área requer revisão dos vínculos'; END IF; n:=coalesce(parcial->>'visibilidade',r.visibilidade); IF r.parent_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.objetos_acesso p WHERE p.id=r.parent_id AND (CASE p.visibilidade WHEN 'privada' THEN 2 WHEN 'compartilhada' THEN 1 ELSE 0 END)>(CASE n WHEN 'privada' THEN 2 WHEN 'compartilhada' THEN 1 ELSE 0 END)) THEN RAISE EXCEPTION 'O filho não pode ampliar a visibilidade do pai'; END IF; FOR v IN SELECT * FROM jsonb_array_elements(coalesce(parcial->'convidados','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(v->>'usuarioId')::uuid) THEN RAISE EXCEPTION 'Usuário inválido'; END IF; END LOOP; UPDATE public.objetos_acesso SET visibilidade=n,convidados=coalesce(parcial->'convidados',convidados),compartilhado_com=CASE WHEN parcial?'compartilhadoCom' THEN ARRAY(SELECT jsonb_array_elements_text(parcial->'compartilhadoCom')::uuid) ELSE compartilhado_com END,updated_at=now(),updated_by=auth.uid() WHERE id=objeto; INSERT INTO public.security_audit_log(user_id,event_type,entity_type,entity_id,context) VALUES(auth.uid(),'administrative_action','objetos_acesso',objeto::text,jsonb_build_object('before',to_jsonb(r),'after',parcial)); END $$;
REVOKE ALL ON FUNCTION public.ppm_alterar_acesso(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_alterar_acesso(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.ppm_validar_filho() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='projeto_subelementos' AND NOT EXISTS(SELECT 1 FROM public.projeto_elementos WHERE id=NEW.elemento_id AND projeto_id=NEW.projeto_id) THEN RAISE EXCEPTION 'Elemento e projeto incompatíveis'; END IF; IF TG_TABLE_NAME='projeto_atualizacoes' THEN IF length(trim(NEW.texto)) NOT BETWEEN 2 AND 2000 THEN RAISE EXCEPTION 'Texto inválido'; END IF; IF NEW.alvo_tipo='projeto' AND NEW.alvo_id<>NEW.projeto_id OR NEW.alvo_tipo='elemento' AND NOT EXISTS(SELECT 1 FROM public.projeto_elementos WHERE id=NEW.alvo_id AND projeto_id=NEW.projeto_id) OR NEW.alvo_tipo='subelemento' AND NOT EXISTS(SELECT 1 FROM public.projeto_subelementos WHERE id=NEW.alvo_id AND projeto_id=NEW.projeto_id) OR NEW.alvo_tipo NOT IN ('projeto','elemento','subelemento') THEN RAISE EXCEPTION 'Contexto inválido'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER ppm_validate BEFORE INSERT OR UPDATE ON public.projeto_subelementos FOR EACH ROW EXECUTE FUNCTION public.ppm_validar_filho(); CREATE TRIGGER ppm_validate BEFORE INSERT ON public.projeto_atualizacoes FOR EACH ROW EXECUTE FUNCTION public.ppm_validar_filho();